// Build alert message from query results
const products = $input.all();
const today = new Date().toLocaleDateString('en-IN', {timeZone: 'Asia/Kolkata'});

let productLines = products.map(p => {
  const d = p.json;
  return `• Product ${d.product_id}
  Stores affected: ${d.high_risk_stores}
  Avg Predicted Demand: ${d.avg_predicted_sales} units/day
  Avg Reorder Quantity: ${d.avg_reorder_qty} units
  Priority: ${d.replenishment_priority}`;
}).join('

');

const subject = `SmartStock AI Alert — ${products.length} Product(s) Require Urgent Review (${today})`;

const body = `SmartStock AI — Daily Inventory Alert
${'='.repeat(60)}

Date: ${today}
Status: ${products.length} HIGH-PRIORITY product(s) detected

Products Requiring Urgent Replenishment:
${'─'.repeat(50)}

${productLines}

${'─'.repeat(50)}

NOTE: Reorder quantities are demand-based estimates (predicted_sales × 7 days).
FreshRetailNet does not provide real-time inventory-on-hand data.
This is an automated alert from SmartStock AI.

For full details, visit the SmartStock AI Streamlit dashboard.`;

return [{json: {subject, body, product_count: products.length}}];

// No high-risk products — log that alert was skipped
console.log('SmartStock AI: No HIGH-priority products found. Alert skipped.');
return [{json: {status: 'skipped', reason: 'No high-priority products detected'}}];
